"""Create a separate diagnostic log collector from the exact checked-out source."""
from pathlib import Path
import shutil
import sys

root = Path(sys.argv[1]).resolve()
destination = Path(sys.argv[2]).resolve()
original = root / 'rust/crates/logmessaged/src/main.rs'
source = original.read_text()
needle = '            let bytes = openpilot_logmessaged::record_bytes::join(parts);\n'
assert source.count(needle) == 1
capture = '''            if let Some(path) = std::env::var_os("PANDA_DIAG_INGRESS") {
                use std::io::Write;
                let mut capture = std::fs::OpenOptions::new().create(true).append(true).open(path)?;
                capture.write_all(&(bytes.len() as u64).to_le_bytes())?;
                capture.write_all(&bytes)?;
            }
'''
destination.mkdir(parents=True, exist_ok=False)
(destination / 'src').mkdir()
(destination / 'src/main.rs').write_text(source.replace(needle, needle + capture))
(destination / 'Cargo.toml').write_text('''[package]
name = "panda-diag-logmessaged"
version = "0.1.0"
edition = "2021"
publish = false

[workspace]

[dependencies]
openpilot-logmessaged = { path = "''' + str(root / 'rust/crates/logmessaged') + '''" }
openpilot-messaging = { path = "''' + str(root / 'rust/crates/messaging') + '''" }
rustix = { version = "1", features = ["time"] }
signal-hook = "0.3"
thiserror = "2"
zmq = "=0.10.0"
''')
shutil.copy(root / 'rust/Cargo.lock', destination / 'Cargo.lock')
lock = (destination / 'Cargo.lock').read_text()
assert lock.startswith('# This file is automatically @generated by Cargo.\n')
assert 'name = "panda-diag-logmessaged"' not in lock
entry = '''[[package]]
name = "panda-diag-logmessaged"
version = "0.1.0"
dependencies = [
 "openpilot-logmessaged",
 "openpilot-messaging",
 "rustix",
 "signal-hook",
 "thiserror 2.0.21",
 "zmq",
]
'''
next_package = '[[package]]\nname = "parking_lot"'
assert lock.count(next_package) == 1
position = lock.index(next_package)
lock = lock[:position] + entry + '\n' + lock[position:]
(destination / 'Cargo.lock').write_text(lock)
